import { useDispatch, useSelector } from 'react-redux'
import { setKeyWordSearchErrorMessage, setKeyWordSearchIsLoading, setKeywordSearchValue, setSearchList, setSelectedCategoryNotFound } from '../../state/searchState/searchSlice';
