import logo from './logo.svg';
import './App.css';
import Header from './components/ui/header';
import SearchPage from './components/ui/SearchPage';
import { useDispatch, useSelector } from 'react-redux';
import ProductsPage from './components/ui/ProductsPage';
import { Toaster } from 'react-hot-toast';
import NewCategoryUpload from './components/ui/NewCategoryUpload';
import DeleteCategory from './components/ui/DeleteCategory';
import AddNewCategoryPage from './components/ui/AddNewCategoryPage';
import { setAddCategoryStateMessage, setAddCategoryStatePercentage, setAddNewCategoryLoading, setCategoryToAdd, setShowCategoryAdd, setWebsocketConnected } from './state/searchState/searchSlice';
import toast from 'react-hot-toast'
import { useEffect, useRef } from 'react'

function App() {
  const filtersObject = useSelector((state)=>state.search.filtersObject)
  const showCategoryUpload = useSelector((state)=> state.search.showCategoryUpload)
   const showCategoryAdd= useSelector((state)=> state.search.showCategoryAdd)
  const showDeleteCategory = useSelector((state)=> state.search.showDeleteCategory)
const dispatch = useDispatch()
const wsRef = useRef(null);
const reconnectTimeoutRef = useRef(null);
const reconnectAttemptsRef = useRef(0);
const MAX_RECONNECT_ATTEMPTS = 5;
const RECONNECT_DELAY = 3000;

useEffect(() => {
  
  let isComponentMounted = true;
  
  const connectWebSocket = () => {
    if (!isComponentMounted) return;
    
    // Clear any existing connection
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    // "wss://FaridaYasserEl-Lahamy-hr-project-backend.hf.space/ws/updates"
    console.log("🔌 Connecting to WebSocket...");
    const ws = new WebSocket("wss://faridayasserel-lahamy-zp-new.hf.space/ws/updates");
    wsRef.current = ws;
    
    // Connection opened
    ws.onopen = () => {
      console.log("✅ WebSocket connected");
      reconnectAttemptsRef.current = 0;
      dispatch(setWebsocketConnected(true));
    };
    
    // Handle incoming messages
    ws.onmessage = (event) => {
      try {
        const msg = JSON.parse(event.data);
        
        // Handle ping
        if (msg.type === "ping") {
          try {
            ws.send("pong");
          } catch (e) {
            console.error("Failed to send pong:", e);
          }
          return;
        }
        
        // Handle snapshot
        if (msg.type === "snapshot") {
          console.log("📦 Received snapshot:", msg.data);
          processSnapshot(msg.data);
          return;
        }
        
        // Handle updates
        if (msg.type === "update") {
          console.log("📦 Received update:", msg.data);
          processUpdates(msg.data);
          return;
        }
        
      } catch (err) {
        console.error("⚠️ Failed to parse message:", err);
      }
    };
    
    // Connection error
    ws.onerror = (error) => {
      console.error("❌ WebSocket error:", error);
    };
    
    // Connection closed
    ws.onclose = (event) => {
      console.log(`🔌 WebSocket closed (code: ${event.code}, reason: ${event.reason})`);
      dispatch(setWebsocketConnected(false));
      
      // Attempt reconnection
      if (isComponentMounted && reconnectAttemptsRef.current < MAX_RECONNECT_ATTEMPTS) {
        reconnectAttemptsRef.current++;
        const delay = RECONNECT_DELAY * reconnectAttemptsRef.current;
        
        console.log(`🔄 Reconnecting in ${delay}ms (attempt ${reconnectAttemptsRef.current}/${MAX_RECONNECT_ATTEMPTS})`);
        
        reconnectTimeoutRef.current = setTimeout(() => {
          connectWebSocket();
        }, delay);
      } else if (reconnectAttemptsRef.current >= MAX_RECONNECT_ATTEMPTS) {
        console.error("❌ Max reconnection attempts reached");
        toast.error("Lost connection to server. Please refresh the page.");
      }
    };
  };
  
  // Process snapshot data
  const processSnapshot = (snapshots) => {
    for (const update of snapshots) {
      const stateMessage = update.state_message;
      if(stateMessage == "category not found" || stateMessage == "category too small"){
        toast.error(stateMessage)
      dispatch(setAddCategoryStateMessage(null))
      dispatch(setCategoryToAdd(null))
     
      }
      else{
      const progress = update.progress
      dispatch(setAddCategoryStateMessage(stateMessage))
      dispatch(setAddCategoryStatePercentage(progress))
      }
      
      
    }
  };
  
  // Process update data
  const processUpdates = (updates) => {
    for (const update of updates) {
      const stateMessage = update.state_message;
      if(stateMessage == "category not found" || stateMessage == "category too small"){
      toast.error(stateMessage)
      dispatch(setAddCategoryStateMessage(null))
      dispatch(setCategoryToAdd(null))
      dispatch(setCategoryToAdd(null))
     
      }
      else{
       const progress = update.progress
      dispatch(setAddCategoryStateMessage(stateMessage))
      dispatch(setAddCategoryStatePercentage(progress))

      if(progress == 100){
           toast.success("Category successfully Added.")
        dispatch(setShowCategoryAdd(false))
        dispatch(setAddCategoryStateMessage(null))
      dispatch(setAddCategoryStatePercentage(null))
      dispatch(setAddNewCategoryLoading(false))
      }
      }

    
    }
  };
  
  
  
  
  // Initial connection
  connectWebSocket();
  
  // Cleanup on unmount
  return () => {
    isComponentMounted = false;
    
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
    }
    
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
  };
  
}, []);






  return (
    <div className="App">
            <Toaster/>

     <Header/>
     {showDeleteCategory == true? <DeleteCategory/> :showCategoryAdd == true? <AddNewCategoryPage/>: filtersObject == null? <SearchPage/>: <ProductsPage/>}
     
    </div>
  );
}

export default App;
