import { Flex, HStack, ProgressCircle, Stack} from '@chakra-ui/react'
import React from 'react'
import FilterComponent from './FilterComponent'
import { useSelector } from 'react-redux'
import ProductsList from './ProductsList'
import FiltersContainer from './FiltersContainer'
import CategoryPath from './CategoryPath'

function ProductsPage() {
 const filtersLoading = useSelector((state)=>state.search.filtersLoading)
 const category_path = useSelector((state)=>state.search.category_path)

  return (
    <Stack w="100%" >
      <CategoryPath category_path = {category_path}/>
    
   <Flex w="100%">
    

    {
        filtersLoading == true? <></>: <FiltersContainer/>
    }
    
{
filtersLoading == true? <HStack  width="100%" justifyContent="center"><ProgressCircle.Root  zIndex = '10' value={null} size = "lg" marginBottom = '10px'>
      <ProgressCircle.Circle>
        <ProgressCircle.Track />
        <ProgressCircle.Range stroke='#0E5870' />
      </ProgressCircle.Circle>
    </ProgressCircle.Root></HStack>:
    <ProductsList/>
}

   </Flex>
   </Stack>
  )
}

export default ProductsPage
