import { Stack, Box,HStack } from '@chakra-ui/react'
import React from 'react'
import { useSelector } from 'react-redux'
import SearchResultListItem from './SearchResultListItem'

function SearchResultsList() {
  const searchList = useSelector((state)=>state.search.searchList)

  return (
        <HStack w="90%" 
        // bg="red" 
        justifyContent="flex-start" marginTop="3px">
    
    <Box w = "84%"
     borderWidth="2px"
          borderColor="#0D3D54"
          borderStyle="solid"
    >
        <Stack w="100%">
         {
        searchList.length == 0? <h1>No Results Found</h1>: searchList.map((searchRes, index) =>{
            return <SearchResultListItem key = {index}  searchItem = {searchRes}  isLast = {index == searchList.length -1}/>
        })
         }
        </Stack>
    </Box>
    </HStack>
  )
}

export default SearchResultsList
