import { Box, HStack, Text} from '@chakra-ui/react'
import React from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { setCategoryPath, setCurrentPage, resetAppliedFilters,  setSelectedFilters, setKeywordSearchValue, setKeyWordSearchIsLoading, setFiltersErrorMessage, setFiltersObject, setFiltersloading, setFullProductsList, setInitialFilters, setKeyWordSearchErrorMessage, setNameToHighlight, setProductsList, setSearchList, setSelectedCategory, setSelectedCategoryNotFound, setTotalItems } from '../../state/searchState/searchSlice'
import api from '../../api';

function SearchResultListItem(props) {
  const dispatch = useDispatch()

  const searchValue = useSelector((state) => state.search.keywordSearchValue)
    ?.trim()
    .toLowerCase()


  const highlightName = (name) => {
    if (!searchValue){
        console.log(name + " is not equal to " + searchValue)
        return name
    }
    
    // Split search value into individual words
    const searchWords = searchValue.trim().toLowerCase().split(/\s+/)
    
    // split on spaces or dashes
    const parts = name.split(/([- \t]+)/) 
    // This keeps the separators ("-", " ", "  ") in the result
    
    return parts.map((part, index) => {
        const clean = part.trim().toLowerCase()
        
        // If it's a separator (space/dash) → return as-is
        if (part.match(/^[- \t]+$/)) {
            return <React.Fragment key={index}>{part}</React.Fragment>
        }
        
        // Check if this word starts with the full searchValue
        if (searchValue.trim().toLowerCase().includes(clean) || 
            clean.startsWith(searchValue.trim().toLowerCase())) {
            return (
                <React.Fragment key={index}>
                    <b style={{ color: 'black' }}>{part.slice(0, searchValue.length)}</b>
                    {part.slice(searchValue.length)}
                </React.Fragment>
            )
        }
        
        // NEW: Check if any word in searchValue is the start of this word
        for (let searchWord of searchWords) {
            if (clean.startsWith(searchWord)) {
                return (
                    <React.Fragment key={index}>
                        <b style={{ color: 'black' }}>{part.slice(0, searchWord.length)}</b>
                        {part.slice(searchWord.length)}
                    </React.Fragment>
                )
            }
        }
        
        // Otherwise return unchanged
        return <React.Fragment  key={index}>{part}</React.Fragment>
    })
}
function resetAll(){
    dispatch(setFiltersObject(null))
    dispatch(setProductsList([]))
    dispatch(setSelectedCategory(null))
    dispatch(setNameToHighlight(""))
    dispatch(setCategoryPath(""))
    dispatch(setFullProductsList([]))
    dispatch(setInitialFilters(null))
    dispatch(setCurrentPage(1))
    dispatch(setKeywordSearchValue(""))
    dispatch(setKeyWordSearchIsLoading(false))
    dispatch(setKeyWordSearchErrorMessage(""))
    dispatch(setSearchList(null))
    dispatch(setFiltersloading(false))
    dispatch(setSelectedCategoryNotFound(false))
    dispatch(setFiltersErrorMessage(""))
    dispatch(setSelectedFilters({}))
    dispatch(setTotalItems(0))
    dispatch(resetAppliedFilters({}))
  }
  async function getFiltersandProducts(){
   try{
    dispatch(setFiltersloading(true))
    dispatch(setFiltersErrorMessage(""))
        dispatch(setSelectedCategoryNotFound(false))

        dispatch(setKeyWordSearchErrorMessage(""))

    dispatch(setSearchList(null))
    const response = await api.post("/get_filters_and_products_first", {
      "sku": props.searchItem.sku,
      "name": props.searchItem.name,
      "category_id": props.searchItem.category_id,
      "page_url": props.searchItem.page_url,
      "applied_filters": {},
      "keys_to_aggregate": []
    })

    console.log(response.data)
    if(response.data["detail"] == "fail"){
      throw Error(response.data["message"])
    }
    if( response.status != 200){
      throw Error()
    }
    if(response.data["detail"] ==  "category not processed yet"){
    console.log("in category not processed yet")
    dispatch(setFiltersloading(false))
    dispatch(setSelectedCategoryNotFound(true))
    dispatch(setKeyWordSearchErrorMessage("The category you are looking for is not processed yet."))
    
    return
    }
    dispatch(setFiltersloading(false))
    dispatch(setTotalItems(response.data["products"].length))
    dispatch(setNameToHighlight(response.data["name_to_highlight"]))
    dispatch(setCategoryPath(response.data["category_path"]))
    dispatch(setFullProductsList(response.data["products"]))
    dispatch(setInitialFilters(response.data["filters_dict"]))
    dispatch(setProductsList(response.data["products"]))
    dispatch(setFiltersObject(response.data["filters_dict"]))
    dispatch(setSelectedCategory(props.searchItem.category_id))
    

   }
   catch(e){
    dispatch(setFiltersloading(false))
    dispatch(setFiltersErrorMessage(String(e)))
    resetAll()
   }
  }

  return (
    <Box 
    textAlign="left"
    marginLeft="10px"
    marginRight= "10px"
    marginBottom="5px"
    marginTop="5px"
    onClick={getFiltersandProducts}
    _hover={{bg: "#D3D3D3", cursor: "pointer"}}
  fontWeight="normal"
fontSize="15px"
color="grey"
    //  borderBottomWidth={props.isLast == false? "2px": null} 
    //       borderBottomColor= {props.isLast == false? "#0D3D54": null} 
    //       borderBottomStyle= {props.isLast == false?  "solid": null}
    >
<HStack justifyContent= "space-between">
     <div>{highlightName(props.searchItem.name)}</div>
     {props.searchItem.category_processed == true? <Text color = "green">{props.searchItem.category_id}</Text> :<Text  color = "red">{props.searchItem.category_id}</Text>}
     </HStack>


    </Box>
  )
}

export default SearchResultListItem
