import { Box, Stack, Text } from '@chakra-ui/react'
import React from 'react'
import { useSelector } from 'react-redux'

function ProductItem(props) {
  const name_to_highlight = useSelector((state) => state.search.name_to_highlight);

    const handleClick = () => {
    if (props.prodLink) {
      window.open(props.prodLink, '_blank'); // opens in a new tab
    }
  };


  return (
<Box 
  cursor={props.prodLink ? "pointer" : "default"} // show pointer if clickable
  onClick={handleClick}
h="100px" borderRadius="15px" border="1px solid black" >
   <Stack>
    <Text color= "black" fontSize="15px"
    fontWeight={props.prodName === name_to_highlight ? "bold" : "normal"}

    >{props.prodName}</Text>
    <Text color= "black" fontSize="10px">{props.sku}</Text>
   </Stack>
</Box>
  )
}

export default ProductItem