import { Stack, createListCollection} from '@chakra-ui/react'
import React from 'react'
import { useSelector } from 'react-redux'
import FilterComponent from './FilterComponent'

function FiltersContainer() {
const filtersObject = useSelector((state)=>state.search.filtersObject)
  return (
   <Stack flex="2" marginLeft="3%" marginBottom="3%">
    {
    
     Object.keys(filtersObject).map((key, index)=>{
         const valuesList = filtersObject[key]
         const itemsList = []
         for(var val of valuesList){
            itemsList.push({"label": val, "value": val})
         }

    const valCollection = createListCollection({items: itemsList})
    return <FilterComponent key = {index} valsCollection = {valCollection} nameOfFilter = {key}/>
     })
    }
   </Stack>
  )
}

export default FiltersContainer
